import "./App.css";
import { useState } from "react";
function App() {
  const { billAmount, setBillAmount } = useState(0);
  const { yourTipPercentage, setYourTipPercentage } = useState(0);
  const { friendsTipPercentage, setFriendsTipPercentage } = useState(0);

  return (
    <div>
      <BillCost billAmount={billAmount} setBillAmount={setBillAmount} />
      <howDoYouLikeService
        yourTipPercentage={yourTipPercentage}
        setYourTipPercentage={setYourTipPercentage}
      />
      <howDoYourFriendsLikeService
        friendsTipPercentage={friendsTipPercentage}
        setFriendsTipPercentage={setFriendsTipPercentage}
      />
    </div>
  );
}

export default App;
